class Solution {
public:
    int maximumWhiteTiles(vector<vector<int>>& tiles, int carpetLen) {
        sort(tiles.begin(), tiles.end());
        int n = (int)tiles.size();
        int ans = 0;
        long long cover = 0;
        int right = 0;
        for (int left = 0; left < n; left++) {
            long long carpetEnd = (long long)tiles[left][0] + carpetLen - 1;
            while (right < n && (long long)tiles[right][1] <= carpetEnd) {
                cover += (long long)tiles[right][1] - tiles[right][0] + 1;
                right++;
            }
            long long total = cover;
            if (right < n && (long long)tiles[right][0] <= carpetEnd) {
                total += carpetEnd - tiles[right][0] + 1;
            }
            if (total > ans) ans = (int)total;
            if (right > left) {
                cover -= (long long)tiles[left][1] - tiles[left][0] + 1;
            } else {
                right = left + 1;
                cover = 0;
            }
        }
        return ans;
    }
};
